-- PT115-S2-Q16. Batch 13.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT115-S2-Q16$batch13$ AND q.stimulus=$batch13$Biologists agree that human beings evolved from a fish, but they disagree about which species of fish. Since biologists agree that frogs are definitely related to the species of fish from which human beings evolved, on the basis of a close match between the mitochondrial DNA of lungfish and that of frogs Dr. Stevens-Hoyt claims that this ancestor must be lungfish. Dr. Grover, on the other hand, contends that mitochondrial DNA evolves too rapidly to be a reliable indicator of relationships between species over long periods of time, and citing the close chemical match between the hemoglobin of coelacanths (a saltwater fish) and that of tadpoles, claims that human beings must be descended from coelacanths.$batch13$ AND q.prompt=$batch13$Which one of the following most accurately describes the role played in the dispute above by the proposition that frogs are definitely related to the species of fish from which human beings evolved?$batch13$ AND q.correct_choice=$batch13$D$batch13$) THEN RAISE EXCEPTION 'Question changed: PT115-S2-Q16'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch13$PT115-S2-Q16$batch13$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT115-S2-Q16'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT115-S2-Q16$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Shared Ground$batch13$, $batch13$Both sides agree humans evolved from a fish and that frogs are related to that fish.$batch13$), (1, $batch13$Stevens-Hoyt$batch13$, $batch13$The ancestor was the lungfish, because lungfish and frog mitochondrial DNA match closely.$batch13$), (2, $batch13$Grover$batch13$, $batch13$The ancestor was the coelacanth, because coelacanth and tadpole hemoglobin match closely. Mitochondrial DNA changes too fast to be reliable over long periods.$batch13$), (3, $batch13$Evaluate$batch13$, $batch13$Each scientist matches a fish to frogs. Lungfish to frog DNA; coelacanth to tadpole hemoglobin. Those matches only point to the human ancestor if frogs are related to that ancestor. So the frog claim is a starting point both sides share.$batch13$), (4, $batch13$Goal$batch13$, $batch13$An assumption both sides use as a starting point.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT115-S2-Q16$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$The frog claim doesn't rule out lungfish. Stevens-Hoyt uses it to argue for lungfish.$batch13$), ($batch13$B$batch13$, $batch13$It doesn't rule out coelacanths either. Grover's tadpole match depends on it.$batch13$), ($batch13$C$batch13$, $batch13$This is the most popular trap. Neither scientist argues the answer must be one of the two fish. Each argues for one, and the frog claim alone doesn't narrow the field to these two.$batch13$), ($batch13$D$batch13$, $batch13$Both arguments match a fish to frogs, which matters only if frogs are related to the ancestor. Both start there.$batch13$), ($batch13$E$batch13$, $batch13$Nobody compares lungfish to coelacanths. Each fish is compared to frogs.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT115-S2-Q16$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
